package app.xiaohe.tests;

import android.content.Context;
import android.content.ContextWrapper;
import android.database.Cursor;
import app.xiaohe.assistant.*;
import org.json.*;
import java.io.File;
import java.lang.reflect.Constructor;
import java.time.*;
import java.util.*;

/** Uses an isolated cache database and no settings, keys or personal database. */
public final class AbsoluteDateSmoke {
  private static int checks=0;
  private static void ok(boolean value,String why){checks++;if(!value)throw new AssertionError("Absolute date "+checks+": "+why);}
  private static long at(String date){return OffsetDateTime.parse(date).toInstant().toEpochMilli();}
  private static JSONObject source(Store store,String content,String captured,String zone)throws Exception {JSONObject m=new JSONObject().put("id",UUID.randomUUID().toString()).put("role","user").put("content",content).put("created",at(captured)).put("capturedAt",at(captured)).put("capturedZone",zone).put("files",new JSONArray()).put("contextMessageIds",new JSONArray());store.put("messages",m);return m;}
  private static JSONObject plan(String content)throws Exception {return new JSONObject().put("kind","intent").put("type","task").put("content",content).put("title",content);}
  private static JSONObject apply(Store store,JSONObject source,JSONObject proposal)throws Exception {new MemoryLedger(store).apply(source,new JSONObject().put("intent","record").put("memories",new JSONArray().put(proposal)),new JSONArray());return store.one("memories",source.getJSONArray("memoryIds").getString(0));}
  private static boolean has(JSONObject answer,String id){JSONArray ids=answer.optJSONArray("evidenceIds");for(int i=0;ids!=null&&i<ids.length();i++)if(ids.optString(i).equals(id))return true;return false;}
  public static void run(Context context)throws Exception {
    final File directory=new File(context.getCacheDir(),"absolute-date-smoke-"+UUID.randomUUID());if(!directory.mkdirs())throw new IllegalStateException("Could not create isolated test directory");final File database=new File(directory,"xiaohe.db");Context isolated=new ContextWrapper(context){@Override public File getDatabasePath(String name){if(!name.equals("xiaohe.db"))throw new IllegalArgumentException("Unexpected fixture database");return database;}};Constructor<Store> constructor=Store.class.getDeclaredConstructor(Context.class);constructor.setAccessible(true);Store store=constructor.newInstance(isolated);
    try{
      JSONObject stage=store.message("user","明天开会",new JSONArray(),UUID.randomUUID().toString());ok(stage.optInt("absoluteDatesVersion")==1&&stage.getJSONArray("absoluteDates").length()==1&&stage.getJSONObject("absoluteDateAnchor").getLong("capturedAt")==stage.getLong("capturedAt"),"The earliest message save freezes relative dates before AI runs");
      JSONObject m=source(store,"明天开会","2030-10-12T23:30:00+08:00","Asia/Shanghai"),r=apply(store,m,plan("开会"));ok(r.getJSONObject("time").getLong("start")==at("2030-10-13T00:00:00+08:00")&&r.getJSONObject("time").getLong("dateStart")==at("2030-10-13T00:00:00+08:00"),"A missing model temporal is filled from the verified original clause at save time");ok(r.getString("dateNormalizedContent").contains("2030年10月13日")&&r.getString("dateNormalizedTitle").contains("2030年10月13日")&&r.getString("content").equals("开会")&&store.one("messages",m.getString("id")).getString("content").equals("明天开会"),"Absolute display text is stored while both original record and utterance remain intact");
      JSONObject next=source(store,"我明天有什么安排","2030-10-13T09:00:00+08:00","Asia/Shanghai"),today=source(store,"我今天有什么安排","2030-10-13T09:00:00+08:00","Asia/Shanghai");ok(!has(ScheduleQuery.answer(store,next),r.getString("id"))&&has(ScheduleQuery.answer(store,today),r.getString("id")),"Tomorrow recorded on October 12 becomes October 13 and never October 14 on a new query");
      JSONObject retry=new JSONObject(m.toString()).put("capturedAt",at("2040-01-01T10:00:00+08:00")).put("capturedZone","America/Los_Angeles");AbsoluteDates.capture(retry);ok(retry.getJSONArray("absoluteDates").getJSONObject(0).getString("date").equals("2030-10-13")&&AbsoluteDates.frozen(retry).getLong("capturedAt")==m.getLong("capturedAt"),"A repeated message cannot reinterpret its frozen mapping using later metadata");
      JSONObject clockSource=source(store,"明天8点开会","2030-10-12T23:30:00+08:00","Asia/Shanghai"),clock=apply(store,clockSource,plan("开会"));ok(clock.getJSONObject("time").optString("state").equals("ambiguous_clock")&&clock.getJSONObject("time").getLong("dateStart")==at("2030-10-13T00:00:00+08:00")&&clock.getJSONObject("time").optLong("start")==0&&clock.optLong("remindAt")==0,"A known date is saved without guessing an unspecified 8 AM or 8 PM");
      JSONObject pendingSource=source(store,"后天去医院","2030-10-12T23:30:00+08:00","Asia/Shanghai");store.pendingRecord(pendingSource,"synthetic offline fixture");JSONObject pending=store.rows("SELECT data FROM memories WHERE created=?",Long.toString(pendingSource.getLong("created"))).getJSONObject(0);JSONArray same=store.rows("SELECT data FROM memories WHERE created=?",Long.toString(pendingSource.getLong("created")));for(int i=0;i<same.length();i++)if(same.getJSONObject(i).optString("sourceId").equals(pendingSource.getString("id")))pending=same.getJSONObject(i);ok(pending.optString("processing").equals("pending")&&pending.getJSONObject("time").getLong("dateStart")==at("2030-10-14T00:00:00+08:00")&&pending.getString("dateNormalizedContent").contains("2030年10月14日"),"Offline pending capture freezes the date immediately, without waiting for retry or AI");
      JSONObject foreign=source(store,"我存了这份资料","2030-10-12T10:00:00+08:00","Asia/Shanghai");foreign.put("linkText","明天开会");store.put("messages",foreign);JSONObject material=apply(store,foreign,plan("明天开会").put("temporal",new JSONObject().put("raw","明天").put("source","link")));ok(material.getJSONObject("time").optString("state").equals("source_time_unknown")&&!material.has("dateNormalizedContent")&&material.getJSONObject("time").optLong("dateStart")==0,"An unknown material author date is never anchored to import day");
      JSONObject quote=source(store,"这张截图里写着明天开会，帮我记一下","2030-10-12T10:00:00+08:00","Asia/Shanghai"),quoted=apply(store,quote,plan("明天开会").put("temporal",new JSONObject().put("raw","明天").put("source","user")));ok(quoted.getJSONObject("time").optLong("dateStart")==0&&!quoted.has("dateNormalizedContent"),"Even a wrongly labelled user temporal cannot turn quoted screenshot tomorrow into import tomorrow");
      JSONObject mixed=source(store,"明天去医院，改天请小林吃饭","2030-10-12T10:00:00+08:00","Asia/Shanghai");new MemoryLedger(store).apply(mixed,new JSONObject().put("memories",new JSONArray().put(plan("去医院")).put(plan("请小林吃饭"))),new JSONArray());JSONObject hospital=store.one("memories",mixed.getJSONArray("memoryIds").getString(0)),meal=store.one("memories",mixed.getJSONArray("memoryIds").getString(1));ok(hospital.getJSONObject("time").optLong("dateStart")==at("2030-10-13T00:00:00+08:00")&&meal.getJSONObject("time").optLong("dateStart")==0&&!meal.has("dateNormalizedContent"),"A mixed source links each record to its own clause rather than sharing the only concrete date");
      JSONObject two=source(store,"今天买菜，明天开会","2030-10-12T10:00:00+08:00","Asia/Shanghai"),multiple=apply(store,two,plan("今天买菜，明天开会").put("temporal",new JSONObject().put("raw","今天买菜，明天开会").put("source","user")));ok(multiple.getJSONObject("time").optString("state").equals("multiple_dates")&&multiple.getJSONObject("time").optLong("start")==0&&multiple.getString("dateNormalizedContent").contains("2030年10月12日")&&multiple.getString("dateNormalizedContent").contains("2030年10月13日"),"Two distinct source dates are never merged by one model temporal");
      JSONObject la=source(store,"明天开会","2030-10-12T23:30:00-07:00","America/Los_Angeles"),laRecord=apply(store,la,plan("开会"));ok(laRecord.getJSONObject("time").getLong("dateStart")==at("2030-10-13T00:00:00-07:00"),"Save-time absolute dates retain the captured timezone");
      JSONObject voice=source(store,"","2030-10-12T23:30:00+08:00","Asia/Shanghai");voice.put("content","明天开会").put("voiceText","明天开会").put("recordedVoiceVerified",true);store.put("messages",voice);ok(voice.getJSONArray("absoluteDates").getJSONObject(0).getString("date").equals("2030-10-13")&&apply(store,voice,plan("开会")).getJSONObject("time").getLong("dateStart")==at("2030-10-13T00:00:00+08:00"),"The first verified recording transcript fills an empty capture using original stage time");JSONObject externalVoice=source(store,"","2030-10-12T23:30:00+08:00","Asia/Shanghai");externalVoice.put("content","明天开会").put("voiceText","明天开会");store.put("messages",externalVoice);ok(externalVoice.getJSONArray("absoluteDates").length()==0,"An external audio transcript is not treated as the user's direct utterance");
      JSONObject url=source(store,"看看https://example.org/明天/资料","2030-10-12T10:00:00+08:00","Asia/Shanghai"),company=source(store,"明天科技公司的资料","2030-10-12T10:00:00+08:00","Asia/Shanghai");ok(url.getJSONArray("absoluteDates").length()==0&&AbsoluteDates.normalizeText(url.getString("content"),m).equals(url.getString("content"))&&AbsoluteDates.normalizeText(company.getString("content"),m).equals(company.getString("content")),"URL paths and recognizable entity suffixes are not rewritten as date words");
      MemoryLedger ledger=new MemoryLedger(store);String version=ledger.history(r.getString("id")).getJSONObject(0).getString("id");JSONObject edited=ledger.edit(new JSONObject().put("id",r.getString("id")).put("content","后天改去医院"),"");ok(!edited.has("dateNormalizedContent")&&edited.getString("content").equals("后天改去医院"),"A manual edit without a new utterance cannot reuse the old source's date display");JSONObject restored=ledger.restoreVersion(version);ok(restored.getString("content").equals("开会")&&restored.getString("dateNormalizedContent").contains("2030年10月13日"),"Restored display text matches the old content snapshot, not the newer edit");
      JSONObject imported=new JSONObject(r.toString()).put("id",UUID.randomUUID().toString());store.put("memories",imported);ok(store.one("memories",imported.getString("id")).getJSONObject("time").getLong("start")==at("2030-10-13T00:00:00+08:00"),"Re-saving an already anchored imported record preserves its event instant");JSONObject week=source(store,"下周去看展","2030-10-12T10:00:00+08:00","Asia/Shanghai"),weekly=apply(store,week,plan("去看展"));ok(weekly.getJSONObject("time").getString("normalizedRaw").contains("2030年10月20日")&&weekly.getJSONObject("time").getString("normalizedRaw").contains("期间"),"A week stays an absolute interval rather than becoming its Monday");
      try(Cursor c=store.getReadableDatabase().rawQuery("SELECT terms FROM memory_fts WHERE memory_id=?",new String[]{r.getString("id")})){ok(c.moveToFirst()&&c.getString(0).contains(MemorySchema.terms("2030年10月13日").split(" ")[0]),"Stored absolute display dates are also searchable in FTS");}
      System.out.println("Absolute date checks passed: "+checks+"; isolated save pipeline, pending/voice captures, source guards and immutable date displays");
    }finally{store.close();android.database.sqlite.SQLiteDatabase.deleteDatabase(database);directory.delete();}
  }
}
